// StreamFocusCards (#2189) — the focused stream rebuilt as a stack of collapsible cards (the
// "Streams Pane Redesign"). Replaces the monolithic StreamCard/AgentEditor with one CollapsibleCard
// each for Persona · Kickoff · Scope · Model & flow. Persona + Kickoff are default-open (they were
// buried before), and the persona pairing is ALWAYS shown — "Worker (default)" when a stream launches
// with no persona assigned. Uses the app's abstracted primitives (CollapsibleCard, Seg, Chip, Code,
// SelectField, RoleChip) + the #2186 PersonaSummary (rendered flat inside the Persona card).
import { useState } from "react";
import type { Flow, Agent } from "@/features/planner/pane/projectPaneData";
import type { ModelId } from "@/app/console/lib/models";
import type { PlanDependency, DependencyRegistry } from "@/features/planner/issues/dependencies";

// modelTier/tierToModelId vendored locally — the real `@/app/console/lib/models` module loads its
// catalog via `@data/console/models.json` at MODULE SCOPE (`DEFAULT_MODEL_ID` calls `.find` on it
// immediately on import), and `@data/*.json` imports aren't supported in this sandbox — so merely
// importing anything from that file crashes at load time with "Cannot read properties of null
// (reading 'find')", regardless of whether modelTier/tierToModelId are ever called.
function modelTier(id: string): string { return id.split("-")[0]; }
function tierToModelId(tier: string): ModelId | undefined {
  const map: Record<string, ModelId> = { haiku: "haiku-4.5" as ModelId, sonnet: "sonnet-4.5" as ModelId, opus: "opus-4.5" as ModelId };
  return map[tier];
}
import { Chip } from "@/shared/ui/data/Chip";
import { Code } from "@/shared/ui/data/Code";
import { SelectField } from "@/shared/ui/controls/Field";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { SectionLabel } from "@/shared/ui/layout/SectionLabel";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";
import { Spacer } from "@/shared/ui/layout/Spacer";

const MONO = "var(--mono)";

// CollapsibleCard inlined verbatim from `@/features/planner/bodies/collapsibleCard` (another AS GRAPH
// SOURCE component) — same nested-provides-tag build limit as RoleChip/Seg below.
function CollapsibleCard({ title, hint, icon, iconTone, right, tone, defaultOpen = false, children }: {
  title: string; hint?: string; icon?: string; iconTone?: string; right?: React.ReactNode;
  tone?: string; defaultOpen?: boolean; children: React.ReactNode;
}) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <Box radius="lg" bg="var(--bg-panel)" pad={[13, 14]} style={{
      border: "1px solid " + (tone ? `color-mix(in oklch, ${tone}, transparent 78%)` : "var(--border-soft)"),
    }}>
      <Row
        onClick={() => setOpen((o) => !o)}
        gap={9}
        style={{ marginBottom: open ? 12 : 0, cursor: "pointer", userSelect: "none" }}
      >
        {icon && (
          <Box as="span" radius={6} bg="var(--bg-elev)" border="soft" style={{
            width: 20, height: 20, flex: "0 0 20px", display: "flex", alignItems: "center", justifyContent: "center",
            fontFamily: MONO, fontSize: 11, color: iconTone ?? tone ?? "var(--fg-dim)",
          }}>{icon}</Box>
        )}
        <Text as="span" size={13} weight={600} style={{ fontFamily: "var(--sans)", color: "var(--fg)" }}>{title}</Text>
        {hint && <Text as="span" mono size={9.5} tone="dim">{hint}</Text>}
        <Spacer />
        {right}
        <Text as="span" tone="dim" mono size={11} style={{ width: 12, textAlign: "center" }}>{open ? "▾" : "▸"}</Text>
      </Row>
      {open && children}
    </Box>
  );
}

// Preview-only stand-in for `useAppStore((s) => s.personas)` — app-internal, unresolvable in this
// sandbox. Same shape, fixed sample data (mirrors the roster personaspanel/personasummary use).
const SAMPLE_PERSONAS = [
  { id: "persona-worker", name: "Worker", role: "worker", blurb: "Implements features end to end.", skills: [], startPrompt: "", model: undefined },
  { id: "persona-reviewer", name: "Reviewer", role: "reviewer", blurb: "Reviews diffs for correctness and style.", skills: [], startPrompt: "", model: undefined },
  { id: "persona-triage", name: "Triage", role: "triage", blurb: "Investigates and routes incoming issues.", skills: [], startPrompt: "", model: undefined },
];
// RoleChip/Seg inlined verbatim from `@/features/planner/pane/focusedPrimitives` (a second AS GRAPH
// SOURCE component) — a direct cross-import to it breaks this component's build (the known nested-
// provides-tag limit hit repeatedly this session; see TerminalBanners/DeploymentBody). Both are tiny,
// pure presentational primitives — cheap to duplicate here.
const ROLES: Record<string, { c: string; label: string }> = {
  planner:  { c: "oklch(0.72 0.10 230)", label: "planner" },
  worker:   { c: "oklch(0.80 0.14 70)",  label: "worker" },
  reviewer: { c: "oklch(0.70 0.12 300)", label: "reviewer" },
  triage:   { c: "oklch(0.72 0.10 195)", label: "triage" },
  tester:   { c: "oklch(0.72 0.13 145)", label: "tester" },
  director: { c: "oklch(0.70 0.14 350)", label: "director" },
};
function RoleChip({ role, mute }: { role: string; mute?: boolean }) {
  const R = ROLES[role] || { c: "var(--fg-dim)", label: role };
  return (
    <Box as="span" className="role" bg={`color-mix(in oklch, ${R.c}, transparent ${mute ? 90 : 84}%)`} style={{
      color: R.c, border: `1px solid color-mix(in oklch, ${R.c}, transparent 72%)`,
    }}>
      <i style={{ background: R.c }} />{R.label}
    </Box>
  );
}
function Seg({ options, value, onChange, tiny }: {
  options: string[]; value: string; onChange?: (v: string) => void; tiny?: boolean;
}) {
  return (
    <Box as="span" className="mono" border="soft" radius={5} style={{
      display: "inline-flex", overflow: "hidden",
      fontSize: tiny ? 9 : 9.5,
    }}>
      {options.map((o, i) => {
        const on = o === value;
        return (
          // eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled segmented cell (local `Seg` primitive); SegmentedControl/.btn would change rendering
          <button key={o} onClick={() => onChange && onChange(o)} style={{
            border: 0, borderRight: i < options.length - 1 ? "1px solid var(--border-soft)" : 0,
            background: on ? "color-mix(in oklch, var(--accent), transparent 84%)" : "transparent",
            color: on ? "var(--accent)" : "var(--fg-dim)",
            padding: "2px 7px", cursor: "pointer", whiteSpace: "nowrap",
          }}>{o}</button>
        );
      })}
    </Box>
  );
}

// PersonaSummary/StreamSharedDeps inlined as simplified local stand-ins — direct cross-imports to
// either broke the build with the same shared/ui/kit resolution failure AlgorithmsInspector hits
// (root cause not isolated to one specific import; removing them together is what actually cleared
// it). Both condense the real components' content rather than reproduce it fully.
function PersonaSummary({ persona, flat }: { persona: { blurb?: string; model?: string; role?: string }; flat?: boolean }) {
  const body = (
    <Stack gap={6}>
      {persona.blurb && <Text as="div" mono size={10} tone="muted" style={{ lineHeight: 1.5 }}>{persona.blurb}</Text>}
      <Text as="span" mono size={9.5} tone={persona.model ? "accent" : "dim"}>{persona.model || "session default model"}</Text>
    </Stack>
  );
  if (flat) return body;
  return <Box bg="var(--bg-panel)" radius={5} pad={[9, 10]} style={{ marginTop: 8, border: "1px solid var(--border-soft)" }}>{body}</Box>;
}
function StreamSharedDeps({ a }: { a: Agent; agents?: Agent[]; dependencies?: PlanDependency[]; registries?: Record<string, DependencyRegistry> }) {
  return (
    <Text as="div" mono size={9.5} tone="dim" style={{ lineHeight: 1.5 }}>
      {a.repo} shares build dependencies with other streams on the same repo — see the Deployment stage for the reconciled lock.
    </Text>
  );
}

const DEFAULT_AGENT: Agent = {
  id: "w1", name: "worker-1", role: "worker", status: "run", repo: "kevin/design-studio", color: "var(--accent)",
  initial: "W", owns: ["src/features/planner/**"], issues: ["#412", "#418"], preset: "default",
  perm: {}, flow: { autonomy: "checkpoint", push: "push-confirm", gate: "soft" },
  ctx: 42000, kickoff: "Implement the Streams stage per #2189 — see the linked issues for scope.",
  scope: "owns: src/features/planner/** · issues: #412, #418", persona: "persona-worker",
} as unknown as Agent;

export function StreamFocusCards({ a = DEFAULT_AGENT, agents, dependencies, registries, onFlow, onModel, onPersona }: {
  a?: Agent;
  /** The whole fleet — used to compute the focused stream's shared-dependency slice (#2191). */
  agents?: Agent[];
  dependencies?: PlanDependency[];
  registries?: Record<string, DependencyRegistry>;
  onFlow?: (streamId: string, flow: Flow) => void;
  onModel?: (streamId: string, model: ModelId | undefined) => void;
  onPersona?: (streamId: string, personaId: string | undefined) => void;
}) {
  const personas = SAMPLE_PERSONAS;
  const assigned = personas.find((p) => p.id === a.persona);
  // Unassigned ⇒ display the packaged Worker persona so the pairing is never blank; the header still
  // reads "Worker (default)" and the picker value stays "" so nothing is written onto the stream.
  const display = assigned ?? personas.find((p) => p.id === "persona-worker");

  // Local echo of model/flow, resynced when the focused stream changes — adjusted DURING render
  // (React's recommended alternative to a sync effect), which also avoids a set-state-in-effect lint.
  const [flow, setFlow] = useState<Flow>(a.flow);
  const [model, setModel] = useState<ModelId | undefined>(a.model);
  const [lastId, setLastId] = useState(a.id);
  if (a.id !== lastId) { setLastId(a.id); setFlow(a.flow); setModel(a.model); }

  const personaName = assigned ? assigned.name : "Worker (default)";
  const personaRole = display?.role ?? "worker";

  return (
    <Stack gap={12} style={{ marginTop: 14 }}>
      {/* PERSONA — the behavioral identity this stream launches as. */}
      <CollapsibleCard
        title="Persona"
        icon="☺"
        defaultOpen
        right={
          <Row gap={7} align="center">
            <Text as="span" size={11} tone="muted">{personaName}</Text>
            <RoleChip role={personaRole} mute />
          </Row>
        }
      >
        <Stack gap={12}>
          {onPersona && (
            <SelectField
              label="launches as"
              hint="the role sets the permission floor"
              value={a.persona ?? ""}
              onChange={(v) => onPersona(a.id, v || undefined)}
            >
              <option value="">worker (default)</option>
              {personas.map((p) => <option key={p.id} value={p.id}>{p.name} · {p.role}</option>)}
            </SelectField>
          )}
          {display && <PersonaSummary persona={display} flat />}
        </Stack>
      </CollapsibleCard>

      {/* KICKOFF — the exact first message the worker receives at launch (the hero card). */}
      <CollapsibleCard
        title="Kickoff"
        icon="➤"
        iconTone="var(--accent)"
        defaultOpen
        right={a.authoredPrompt ? <Chip color="var(--accent)">authored</Chip> : <Chip>generated</Chip>}
      >
        <Stack gap={11}>
          {a.authoredPrompt && (
            <Text as="div" mono size={10} tone="muted" style={{ lineHeight: 1.5 }}>
              Launches from an authored kickoff script — <Box as="span" className="glob">{a.authoredPrompt}</Box>. The generated default below is the fallback.
            </Text>
          )}
          <Code>{a.kickoff}</Code>
          <details>
            <summary className="mono" style={{ cursor: "pointer", fontSize: 10, color: "var(--fg-dim)", userSelect: "none" }}>
              Lane context — CLAUDE.local.md
            </summary>
            <Code style={{ marginTop: 6 }}>{a.scope}</Code>
          </details>
        </Stack>
      </CollapsibleCard>

      {/* SCOPE — repo · owned globs · issues. */}
      <CollapsibleCard title="Scope" icon="⎇" right={<Text as="span" mono size={9.5} tone="dim">{a.repo}</Text>}>
        <Row className="mono" gap={6} wrap style={{ fontSize: 9.5, color: "var(--fg-muted)" }}>
          <Text as="span" style={{ color: "var(--info)" }}>⎇ {a.repo}</Text>
          <Text as="span" tone="dim">·</Text>
          <Box as="span">owns</Box>
          {a.owns.map((o) => <Box as="span" key={o} className="glob">{o}</Box>)}
          {a.issues.map((i) => <Text as="span" key={i} tone="accent">{i}</Text>)}
        </Row>
      </CollapsibleCard>

      {/* SHARED DEPENDENCIES — this stream's slice: is its repo shared, with whom, and the deps it
          declares. Only meaningful with a fleet of 2+ streams (sharing is impossible with one). */}
      {(agents?.length ?? 0) >= 2 && (
        <CollapsibleCard title="Shared dependencies" icon="⇄">
          <StreamSharedDeps a={a} agents={agents} dependencies={dependencies} registries={registries} />
        </CollapsibleCard>
      )}

      {/* MODEL & FLOW — the per-stream launch knobs. */}
      <CollapsibleCard
        title="Model & flow"
        icon="⚙"
        right={<Text as="span" mono size={9.5} tone="dim">{model ? modelTier(model) : "default model"} · {flow.autonomy}</Text>}
      >
        <Stack gap={14}>
          <Stack gap={6}>
            <SectionLabel size={9.5}>model</SectionLabel>
            <Row gap={8} align="center">
              <Seg
                options={["default", "haiku", "sonnet", "opus"]}
                value={model ? modelTier(model) : "default"}
                onChange={(v) => { const m = v === "default" ? undefined : tierToModelId(v); setModel(m); onModel?.(a.id, m); }}
              />
              <Text as="span" mono size={9} tone="dim">
                {model ? `claude --model ${modelTier(model)}` : "uses the global default"}
              </Text>
            </Row>
          </Stack>
          <Stack gap={9}>
            <SectionLabel size={9.5}>flow</SectionLabel>
            <Row gap={8} align="center">
              <Text as="span" mono size={10} tone="muted" style={{ flex: "0 0 64px" }}>autonomy</Text>
              <Seg options={["continuous", "checkpoint", "confirm"]} value={flow.autonomy}
                onChange={(v) => { const next = { ...flow, autonomy: v }; setFlow(next); onFlow?.(a.id, next); }} />
            </Row>
            <Row gap={8} align="center">
              <Text as="span" mono size={10} tone="muted" style={{ flex: "0 0 64px" }}>push</Text>
              <Seg options={["auto-PR", "push-confirm", "commit-only", "none"]} value={flow.push}
                onChange={(v) => { const next = { ...flow, push: v }; setFlow(next); onFlow?.(a.id, next); }} />
            </Row>
            <Row gap={8} align="center">
              <Text as="span" mono size={10} tone="muted" style={{ flex: "0 0 64px" }}>gate</Text>
              <Seg options={["soft", "hard"]} value={flow.gate}
                onChange={(v) => { const next = { ...flow, gate: v }; setFlow(next); onFlow?.(a.id, next); }} />
              <Text as="span" mono size={9} tone="dim">
                {flow.gate === "hard" ? "blocks on violation" : "warns, continues"}
              </Text>
            </Row>
          </Stack>
        </Stack>
      </CollapsibleCard>
    </Stack>
  );
}
